// Strict validator for the finite JSON-schema subset generated by our Rust domain DTOs.
// The renderer preserves u64 decimal strings instead of coercing them to numbers.
type Schema =
  | boolean
  | {
      $ref?: string;
      $defs?: Record<string, Schema>;
      type?: string | string[];
      const?: unknown;
      enum?: unknown[];
      anyOf?: Schema[];
      oneOf?: Schema[];
      allOf?: Schema[];
      properties?: Record<string, Schema>;
      required?: string[];
      additionalProperties?: Schema;
      items?: Schema;
      minimum?: number;
      maximum?: number;
      maxLength?: number;
      pattern?: string;
    };
function accepts(
  schema: Schema,
  value: unknown,
  root: Schema,
  depth = 0,
): boolean {
  if (depth > 40) return false;
  if (typeof schema === "boolean") return schema;
  if (schema.$ref) {
    if (!schema.$ref.startsWith("#/$defs/") || typeof root === "boolean")
      return false;
    if (
      schema.$ref === "#/$defs/Decimal" &&
      (typeof value !== "string" ||
        !/^(0|[1-9][0-9]{0,19})$/.test(value) ||
        BigInt(value) > 18446744073709551615n)
    )
      return false;
    const target = root.$defs?.[schema.$ref.slice(8)];
    return target !== undefined && accepts(target, value, root, depth + 1);
  }
  if (schema.const !== undefined && value !== schema.const) return false;
  if (schema.enum && !schema.enum.includes(value)) return false;
  if (
    schema.anyOf &&
    !schema.anyOf.some((s) => accepts(s, value, root, depth + 1))
  )
    return false;
  if (
    schema.oneOf &&
    schema.oneOf.filter((s) => accepts(s, value, root, depth + 1)).length !== 1
  )
    return false;
  if (
    schema.allOf &&
    !schema.allOf.every((s) => accepts(s, value, root, depth + 1))
  )
    return false;
  if (Array.isArray(schema.type))
    return schema.type.some((type) =>
      accepts({ ...schema, type }, value, root, depth + 1),
    );
  if (schema.type === "null") return value === null;
  if (schema.type === "string")
    return (
      typeof value === "string" &&
      (schema.maxLength === undefined ||
        [...value].length <= schema.maxLength) &&
      (!schema.pattern || new RegExp(schema.pattern).test(value))
    );
  if (schema.type === "boolean") return typeof value === "boolean";
  if (schema.type === "integer" || schema.type === "number")
    return (
      typeof value === "number" &&
      Number.isFinite(value) &&
      (schema.type !== "integer" || Number.isSafeInteger(value)) &&
      (schema.minimum === undefined || value >= schema.minimum) &&
      (schema.maximum === undefined || value <= schema.maximum)
    );
  if (schema.type === "array")
    return (
      Array.isArray(value) &&
      value.length <= 10240 &&
      value.every((v) => accepts(schema.items ?? true, v, root, depth + 1))
    );
  if (schema.type === "object") {
    if (typeof value !== "object" || value === null || Array.isArray(value))
      return false;
    if (schema.required?.some((k) => !Object.hasOwn(value, k))) return false;
    return Object.entries(value).every(([key, item]) =>
      accepts(
        Object.hasOwn(schema.properties ?? {}, key)
          ? schema.properties![key]
          : (schema.additionalProperties ?? true),
        item,
        root,
        depth + 1,
      ),
    );
  }
  return true;
}
export function parseDomain<T>(schema: unknown, value: unknown): T {
  if (!accepts(schema as Schema, value, schema as Schema))
    throw new Error("统一来源响应无效，请重新读取。");
  return value as T;
}
